	'k75b64f03' => 'Sa 09:00–12:00 · €45 · 8 Plätze',
	'k7601b0e3' => 'Betriebshygiene',
	'k76e613c5' => '2-wöchiges Praktikum',
	'k77c1ea2b' => 'Quereinstieg',
	'k77fdf66f' => 'Gibt es Stipendienplätze für Lernende, die finanzielle Unterstützung benötigen?',
	'k7882a4b5' => 'Schritt 4',
	'k78efcae6' => 'Fahrrad',
